Topological sorting for Directed Acyclie Graph (DAG) is a linear ordering of vertices such that for every directed edge u v, vertex u comes before v in the ordering. Topological Sorting for a graph is not possible if the graph is not a DAG. Now write a C/C++ Program with the following input and Output. Input: 5 2, 5 0, 4 0, 4 1, 2 3, 3 1 Output: 5 4 2 3 1 0

```
#include <bits/stdc++.h>
using namespace std;

// Function to perform DFS and topological sorting
void topologicalSortUtil(int v, vector<vector<int>> &adj, vector<bool> &visited, stack<int> &st) {
// Mark the current node as visited
visited[v] = true;

// Recur for all adjacent vertices
for (int i : adj[v]) {
if (!visited[i])
topologicalSortUtil(i, adj, visited, st);
}

// Push current vertex to stack which stores the result
st.push(v);
}

vector<vector<int>> constructAdj(int V, vector<vector<int>> &edges) {
vector<vector<int>> adj(V);

for (auto it : edges) {
adj[it[0]].push_back(it[1]);
}

return adj;
}

// Function to perform Topological Sort
vector<int> topologicalSort(int V, vector<vector<int>> &edges) {
// Stack to store the result
stack<int> st;

vector<bool> visited(V, false);
vector<vector<int>> adj = constructAdj(V, edges);

// Call the recursive helper function for all vertices
for (int i = 0; i < V; i++) {
if (!visited[i])
topologicalSortUtil(i, adj, visited, st);
}

vector<int> ans;

// Append contents of stack
while (!st.empty()) {
ans.push_back(st.top());
st.pop();
}

return ans;
}

int main() {
int V = 6;
vector<vector<int>> edges = {
{2, 3}, {3, 1}, {4, 0}, {4, 1}, {5, 0}, {5, 2}
};

vector<int> ans = topologicalSort(V, edges);

for (int node : ans) {
cout << node << " ";
}
cout << endl;

return 0;
}
```

