We are given an array of integers and a range, we need to find whether the subarray which falls in this range has values in the form of a mountain or not. All values of the subarray are said to be in the form of a mountain if either all values are increasing or decreasing or first increasing and then decreasing. Write a C/C++ Program that shows input is a Mountain sequence or Not Mountain sequence.

```
#include <bits/stdc++.h>
using namespace std;

#define ll long long

bool isMountain(vector<ll> a) {
ll n = a.size();

if (n < 3)
return false;

ll i = 1;

// Increasing part
while (i < n && a[i] > a[i - 1]) {
i++;
}

// Peak cannot be first or last
if (i == 1 || i == n)
return false;

// Decreasing part
while (i < n && a[i] < a[i - 1]) {
i++;
}

return i == n;
}

int main() {
ll n;
cin >> n;

vector<ll> a(n);
for (ll i = 0; i < n; i++) {
cin >> a[i];
}

if (isMountain(a)) {
cout << "Mountain" << endl;
} else {
cout << "Not Mountain" << endl;
}

return 0;
}
```

